define({"topics":[{"title":"<span class=\"ph\">Shutting down the host computer<\/span>","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_26.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e122534","topics":[]},{"title":"Integrated Cooling Cabinet(ICC) Power Off","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_ICCPowerOff_3.html","attributes":{"data-id":"id_2024779"},"menu":{"hasChildren":false},"tocID":"id_2024779-d46e122637","topics":[]},{"title":"Applying LOTO - Main Disconnect Panel (MDP)","shortdesc":"<p class=\"shortdesc\"><span class=\"ph uicontrol\">Note: <\/span>Prior to applying LOTO to the system do the Disk Wipe procedure, which can be found on the documentation library. Search on document 5500610-1. Apply LOTO to the MDP or the facility PDU before removing power to these items. Facility-level LOTO must be done by an electrician.<\/p>","href":"t_Applying-LOTO-MDP-Premier_Victor_Prime_5.html","attributes":{"data-id":"id_2001934"},"menu":{"hasChildren":false},"tocID":"id_2001934-d46e122738","topics":[]},{"title":"Removing ICC temperature flow meter sensor","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_RemovingICCTempFlowMeterSensor.html","attributes":{"data-id":"id_2026468"},"menu":{"hasChildren":true},"tocID":"id_2026468-d46e122842","next":"id_2026468-d46e122842"},{"title":"Installing ICC temperature flow meter sensor","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_InstallingICCTempFlowMeterSensor.html","attributes":{"data-id":"id_2026469"},"menu":{"hasChildren":false},"tocID":"id_2026469-d46e123045","topics":[]},{"title":"Checking coolant level and filling","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_CheckingCoolantLevelAndFilling_5.html","attributes":{"data-id":"id_2013140"},"menu":{"hasChildren":false},"tocID":"id_2013140-d46e123146","topics":[]},{"title":"Removing LOTO - Main Disconnect Panel (MDP)","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the MDP or the facility PDU before restoring power to these items. Facility-level LOTO must be done by an electrician.<\/p>","href":"t_Removing-LOTO-MDP-Premier_Victor_Prime_4.html","attributes":{"data-id":"id_2001935"},"menu":{"hasChildren":false},"tocID":"id_2001935-d46e123247","topics":[]},{"title":"Integrated Cooling Cabinet(ICC) Power On","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_ICCPowerOn_starter_3.html","attributes":{"data-id":"id_2024780"},"menu":{"hasChildren":false},"tocID":"id_2024780-d46e123349","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_26.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e123450","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the beginning of some procedures and at the end of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_Parent_24.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e123552","topics":[]}]});